**Arquivo:** `plus-ms-auth/src/auth/auth.service.ts`

Mudanças:

```ts
interface DbUser {
  id: string;
  email: string;
  name: string;          // ← novo
  role: string;
  password_hash: string;
}

function buildTokens(userId: string, email: string, name: string, role: string) {
  const token = jwt.sign(
    { sub: userId, email, name, roles: [role] },   // ← name no payload
    ACCESS_SECRET,
    { expiresIn: 900 },
  );
  const refresh = jwt.sign({ sub: userId }, REFRESH_SECRET, { expiresIn: 604800 });
  return { token, refresh };
}

export async function signupService(
  email: string,
  password: string,
  name: string,           // ← novo parâmetro
): Promise<{ token: string; refresh: string; userId: string }> {
  const passwordHash = await bcrypt.hash(password, BCRYPT_ROUNDS);

  let user: DbUser;
  try {
    const { rows } = await pool.query<DbUser>(
      `INSERT INTO users (email, password_hash, name)
       VALUES ($1, $2, $3)
       RETURNING id, email, name, role, password_hash`,    // ← name no RETURNING
      [email, passwordHash, name],
    );
    user = rows[0];
  } catch (err: unknown) {
    if ((err as { code?: string }).code === "23505") {
      throw new AppError("Email já cadastrado", 409);
    }
    throw err;
  }

  const { token, refresh } = buildTokens(user.id, user.email, user.name, user.role);
  await persistRefreshToken(user.id, refresh);
  return { token, refresh, userId: user.id };
}

export async function loginService(
  email: string,
  password: string,
): Promise<{
  token: string;
  refresh: string;
  user: { id: string; email: string; name: string; roles: string[] };   // ← name
}> {
  const { rows } = await pool.query<DbUser>(
    `SELECT id, email, name, role, password_hash FROM users WHERE email = $1`,
    [email],
  );

  const dbUser = rows[0];
  const passwordMatch = await bcrypt.compare(password, dbUser?.password_hash ?? DUMMY_HASH);
  if (!dbUser || !passwordMatch) throw new AppError("Credenciais inválidas", 401);

  const { token, refresh } = buildTokens(dbUser.id, dbUser.email, dbUser.name, dbUser.role);
  await persistRefreshToken(dbUser.id, refresh);

  return {
    token,
    refresh,
    user: { id: dbUser.id, email: dbUser.email, name: dbUser.name, roles: [dbUser.role] },
  };
}
```

`assignRoleService` e `removeRoleService` também precisam incluir `name` no `SELECT`/`RETURNING` por consistência da interface `DbUser`.

